import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const timelines = [];
  let disposed = false;

  root.userData.handlers = {};

  const makeMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makePlane = (width, height, material, z = 0) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    root.add(mesh);
    return mesh;
  };

  const surfaceMaterial = makeMaterial();
  surfaceMaterial.colorNode = mix(
    color('#0b0b10'),
    color('#16161d'),
    uv().y
  );

  makePlane(3.45, 2.55, surfaceMaterial, -0.08);

  const imageMaterial = makeMaterial({ color: '#e8ecf2' });
  const imagePlane = makePlane(3.18, 1.99, imageMaterial, 0);

  const accentMaterial = makeMaterial({ color: '#ff2a38' });
  makePlane(0.08, 1.99, accentMaterial, 0.025);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    textObject.position.set(-1.48, -1.12, 0.08);
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      ownedTextures.push(texture);
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    });
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    for (const texture of ownedTextures) {
      texture.dispose?.();
    }

    root.userData.handlers = {};
  };

  return root;
}
